(()=>{document.querySelectorAll("img").forEach(e=>{e.addEventListener("mousedown",function(e){e.preventDefault()}),e.addEventListener("contextmenu",function(e){e.preventDefault()})}),window.addEventListener("scroll",function(){const e=document.querySelector(".socialIconsHeader");window.scrollY>0?e.classList.add("scroll"):e.classList.remove("scroll")});const e=document.getElementById("log_In_Form");let t=document.getElementById("password_Hide"),n=document.getElementById("password_Visible"),s=document.getElementById("Userpassword");t.addEventListener("click",()=>{"password"===s.type&&(s.type="text",t.style.display="none",n.style.display="block")}),n.addEventListener("click",()=>{"text"===s.type&&(s.type="password",t.style.display="block",n.style.display="none")}),e.addEventListener("submit",e=>{e.preventDefault()})})();